-- v8: each event chooses its badge design + 10 ready-made designs (safe to run twice)
ALTER TABLE events ADD COLUMN IF NOT EXISTS badge_template_id INT(11) DEFAULT NULL AFTER max_attendees;
ALTER TABLE events ADD CONSTRAINT events_badge_fk FOREIGN KEY IF NOT EXISTS (badge_template_id) REFERENCES badge_templates (id) ON DELETE SET NULL;

